function __kgEsc(t) {
  return String(t == null ? "" : t).replace(/[&<>"]/g, function (c) {
    return { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c];
  });
}

function __kgFormParts(steps, levelName, tagline, teamName) {
  var esc = __kgEsc;
  var lines = function (n) {
    var out = "";
    for (var i = 0; i < n; i++) out += '<div class="line"></div>';
    return out;
  };
  var groups = [];
  steps.forEach(function (st) {
    var name = st.group || "Steps";
    var last = groups[groups.length - 1];
    if (last && last.name === name) last.items.push(st);
    else groups.push({ name: name, items: [st] });
  });
  var overview = groups
    .map(function (g) {
      return (
        '<div class="grp"><b>' + esc(g.name) + "</b><ul>" +
        g.items.map(function (st) { return "<li>&#9744; " + esc(st.title) + (st.optional ? " (optional)" : "") + "</li>"; }).join("") +
        "</ul></div>"
      );
    })
    .join("");
  var cover =
    '<section class="cover"><div class="eyebrow">Kloud &middot; Paper form</div><h1>' + esc(levelName) + " build form</h1>" +
    '<p class="tag">' + esc(tagline || "") + " &middot; " + steps.length + " steps</p>" +
    '<div class="meta"><span>Name</span><span>Date</span><span>Team: ' + esc(teamName || "") + "</span></div>" +
    '<div class="label">Describe your task in one or two sentences</div>' + lines(4) +
    '<div class="label">What is on this form</div><div class="overview">' + overview + "</div>" +
    '<p class="note">Write by hand, one page per step. When you are done, type your answers into the guided builder at the same difficulty level to generate your build guide. Do not write passwords, patient data, or confidential details on this form.</p></section>';
  var pages = steps
    .map(function (st, i) {
      var qs = (st.followUps || []).map(function (q) { return "<li>" + esc(q) + "</li>"; }).join("");
      var ds = (st.decisions || [])
        .map(function (d) {
          return '<div class="yn"><span>' + esc(d.question) + '</span><span class="box">Yes &#9744; &nbsp; No &#9744;</span></div>';
        })
        .join("");
      var rows = ds ? 7 : qs ? 12 : 16;
      return (
        '<section class="step"><div class="eyebrow">' + esc(levelName) + (st.group ? " &middot; " + esc(st.group) : "") + " &middot; Step " + (i + 1) + " of " + steps.length +
        (st.optional ? " &middot; Optional" : "") + "</div><h2>" + esc(st.title) + '</h2><p class="prompt">' + esc(st.prompt) + "</p>" +
        (qs ? '<div class="covered"><b>Think about:</b><ul>' + qs + "</ul></div>" : "") +
        (st.exampleRule ? '<p class="rule"><b>Example rule:</b> ' + esc(st.exampleRule) + "</p>" : "") +
        '<div class="label">Your answer</div>' + (st.placeholder ? '<p class="tip">' + esc(st.placeholder) + "</p>" : "") + lines(rows) +
        (ds ? '<div class="decisions"><b>Tick Yes or No</b>' + ds + "</div>" : "") +
        '<div class="foot">Kloud &middot; ' + esc(teamName || "") + " &middot; " + esc(levelName) + "</div></section>"
      );
    })
    .join("");
  return cover + pages;
}

function __kgFormCss() {
  return (
    "@page{margin:14mm}*{box-sizing:border-box;-webkit-print-color-adjust:exact;print-color-adjust:exact}" +
    "body{font-family:'Segoe UI',Arial,sans-serif;color:#111;font-size:11pt;margin:0}" +
    ".cover,.step{page-break-after:always;break-after:page}body>section:last-child{page-break-after:auto;break-after:auto}" +
    "h1{font-size:24pt;margin:4pt 0}h2{font-size:17pt;margin:4pt 0 2pt}.tag{color:#475569;margin:0 0 6pt}" +
    ".eyebrow{font-size:8.5pt;letter-spacing:.12em;text-transform:uppercase;color:#2563eb;font-weight:700}" +
    ".prompt{font-weight:600;margin:4pt 0 8pt}.covered{border:1px solid #cbd5e1;border-radius:6px;padding:6pt 10pt;font-size:9.5pt;background:#f8fafc}" +
    ".covered ul{margin:4pt 0 0 14pt;padding:0}.rule{font-size:9.5pt;color:#4c1d95;margin:8pt 0 0}" +
    ".label{font-size:8.5pt;font-weight:700;text-transform:uppercase;letter-spacing:.1em;color:#64748b;margin:12pt 0 0}" +
    ".tip{font-size:9pt;color:#64748b;font-style:italic;margin:3pt 0 0}" +
    ".line{height:8mm;border-bottom:1px solid #94a3b8}.meta{display:flex;gap:18pt;margin:14pt 0 6pt}" +
    ".meta span{flex:1;border-bottom:1px solid #111;padding-bottom:3pt;font-size:9pt;color:#475569}" +
    ".overview{display:flex;gap:18pt;margin-top:6pt}.grp{flex:1;font-size:9.5pt}.grp ul{list-style:none;margin:4pt 0 0;padding:0}.grp li{margin:2pt 0}" +
    ".note{font-size:9pt;color:#475569;margin-top:14pt}.decisions{margin-top:10pt;font-size:10pt}" +
    ".yn{display:flex;justify-content:space-between;gap:12pt;padding:4pt 0;border-bottom:1px dotted #cbd5e1}.box{white-space:nowrap}" +
    ".foot{margin-top:10pt;font-size:8pt;color:#94a3b8}" +
    "@media screen{html{background:#cbd5e1}body{padding:18px 0}" +
    ".cover,.step,.sheet{background:#fff;width:210mm;max-width:calc(100% - 24px);min-height:297mm;margin:0 auto 18px;padding:14mm;box-shadow:0 2px 10px rgba(15,23,42,.25)}}"
  );
}

function __kgWrapHtml(title, body) {
  return '<!doctype html><html><head><meta charset="utf-8"><title>' + __kgEsc(title) + "</title><style>" + __kgFormCss() + "</style></head><body>" + body + "</body></html>";
}

function __kgFormHtml(steps, levelName, tagline, teamName) {
  return __kgWrapHtml("Kloud - " + levelName + " paper form", __kgFormParts(steps, levelName, tagline, teamName));
}

function __kgFormHtmlMany(levels, teamName) {
  return __kgWrapHtml(
    "Kloud - all paper forms",
    levels.map(function (l) { return __kgFormParts(l.steps, l.name, l.tagline, teamName); }).join("")
  );
}

function __kgPreviewOverlay(title, options, build, initial) {
  var old = document.getElementById("kg-preview");
  if (old) old.remove();
  var wrap = document.createElement("div");
  wrap.id = "kg-preview";
  wrap.setAttribute("role", "dialog");
  wrap.setAttribute("aria-modal", "true");
  wrap.setAttribute("aria-label", title);
  wrap.style.cssText = "position:fixed;top:0;right:0;bottom:0;left:0;z-index:2147483000;background:rgba(15,23,42,.72);display:flex;flex-direction:column;padding:12px;box-sizing:border-box;font-family:'Segoe UI',Arial,sans-serif";
  var bar = document.createElement("div");
  bar.style.cssText = "display:flex;flex-wrap:wrap;align-items:center;gap:10px;background:#fff;color:#0f172a;border-radius:10px 10px 0 0;padding:10px 14px";
  var heading = document.createElement("strong");
  heading.textContent = title;
  bar.appendChild(heading);
  var select = null;
  if (options && options.length > 1) {
    var label = document.createElement("label");
    label.style.cssText = "display:flex;align-items:center;gap:6px;font-size:14px";
    label.appendChild(document.createTextNode("Show:"));
    select = document.createElement("select");
    select.style.cssText = "padding:5px 8px;border:1px solid #94a3b8;border-radius:8px;font-size:14px;background:#fff;color:#0f172a";
    options.forEach(function (o) {
      var opt = document.createElement("option");
      opt.value = o.value;
      opt.textContent = o.label;
      if (o.value === initial) opt.selected = true;
      select.appendChild(opt);
    });
    label.appendChild(select);
    bar.appendChild(label);
  }
  var info = document.createElement("span");
  info.style.cssText = "font-size:13px;color:#475569";
  bar.appendChild(info);
  var spacer = document.createElement("span");
  spacer.style.flex = "1";
  bar.appendChild(spacer);
  var mkBtn = function (text, primary) {
    var b = document.createElement("button");
    b.type = "button";
    b.textContent = text;
    b.style.cssText = "padding:8px 16px;border-radius:10px;font-size:14px;font-weight:600;cursor:pointer;" + (primary ? "background:#2563eb;color:#fff;border:1px solid #2563eb" : "background:#fff;color:#1e293b;border:1px solid #94a3b8");
    return b;
  };
  var printBtn = mkBtn("Print", true);
  var closeBtn = mkBtn("Close", false);
  bar.appendChild(printBtn);
  bar.appendChild(closeBtn);
  var hint = document.createElement("div");
  hint.style.cssText = "background:#eff6ff;color:#1e3a8a;font-size:13px;padding:6px 14px";
  hint.textContent = "This is how it will look on paper. Choose Print, then pick a printer, or choose Save as PDF as the destination.";
  var frame = document.createElement("iframe");
  frame.title = title;
  frame.style.cssText = "flex:1;width:100%;border:0;background:#cbd5e1;border-radius:0 0 10px 10px";
  wrap.appendChild(bar);
  wrap.appendChild(hint);
  wrap.appendChild(frame);

  var previousOverflow = document.body.style.overflow;
  var onKey;
  var close = function () {
    document.removeEventListener("keydown", onKey, true);
    document.body.style.overflow = previousOverflow;
    wrap.remove();
  };
  onKey = function (e) {
    if (e.key === "Escape") {
      e.stopPropagation();
      close();
    }
  };
  var render = function () {
    var html = build(select ? select.value : initial);
    var pages = (html.match(/<section class="(?:cover|step|sheet)"/g) || []).length;
    info.textContent = pages + (pages === 1 ? " page" : " pages");
    frame.srcdoc = html;
  };
  if (select) select.addEventListener("change", render);
  printBtn.addEventListener("click", function () {
    frame.contentWindow.focus();
    frame.contentWindow.print();
  });
  closeBtn.addEventListener("click", close);
  document.addEventListener("keydown", onKey, true);
  document.body.style.overflow = "hidden";
  document.body.appendChild(wrap);
  render();
  printBtn.focus();
}

function __kgPrintForms(levels, currentId, teamName) {
  var options = levels.map(function (l) {
    return { value: l.id, label: l.name + " (" + l.steps.length + " steps)" };
  });
  if (levels.length > 1) options.push({ value: "all", label: "All levels together" });
  __kgPreviewOverlay(
    "Paper form preview",
    options,
    function (value) {
      if (value === "all") return __kgFormHtmlMany(levels, teamName);
      var level = levels.filter(function (l) { return l.id === value; })[0] || levels[0];
      return __kgFormHtml(level.steps, level.name, level.tagline, teamName);
    },
    currentId
  );
}

function __kgPrintGuide(markdown, title) {
  var body = '<section class="sheet"><pre style="white-space:pre-wrap;word-wrap:break-word;font-family:inherit;margin:0;line-height:1.5">' + __kgEsc(markdown) + "</pre></section>";
  __kgPreviewOverlay(
    "Build guide preview",
    [{ value: "guide", label: title }],
    function () { return __kgWrapHtml(title, body); },
    "guide"
  );
}

function __kgFetch(url, init, ms) {
  if (location.protocol === "file:") {
    return Promise.reject(new Error("AI drafting is not available in the offline file"));
  }
  var ctl = new AbortController();
  var timedOut = false;
  var outer = init && init.signal;
  if (outer) {
    if (outer.aborted) ctl.abort();
    else outer.addEventListener("abort", function () { ctl.abort(); });
  }
  var timer = setTimeout(function () { timedOut = true; ctl.abort(); }, ms);
  return fetch(url, Object.assign({}, init, { signal: ctl.signal })).then(
    function (res) { clearTimeout(timer); return res; },
    function (err) {
      clearTimeout(timer);
      if (timedOut) throw new Error("the AI service did not respond within " + Math.round(ms / 1000) + " seconds");
      throw err;
    }
  );
}

function __kgJson(res) {
  return res.text().then(function (text) {
    try {
      return JSON.parse(text);
    } catch (e) {
      throw new Error("the AI service is not available here (HTTP " + res.status + ")");
    }
  });
}

function __kgGo(id) {
  var el = document.getElementById(id);
  if (el) el.scrollIntoView({ behavior: "smooth", block: "start" });
}

